<script>
$(document).ready(function(){
  var scrollpos,url,newurl,dataurl,lastItem,wh,data_name,top,offset_val=0,next_val,parent_top;
  console.log('url change disabled newurl 2');

  wh = $(window).height()-100;

  $(window).scroll(function(){
    scrollpos = $(this).scrollTop() + wh;
    url = document.location.pathname+ '';
    $('.post-body-content-wrap').map(function (){
      if(scrollpos>$(this).offset().top && scrollpos<$(this).offset().top + $(this).height()){
         lastItem = $(this).data('url');
      }
    });
    Addactive($('.post-audio-author-wrap'),lastItem);
    if(lastItem){  
       newurl = url.split('/').slice(0,-1).join('/')+'/'+lastItem;
    }else{
      {% set url1 = content.absolute_url|split('/',4) %}
      {% set len = url1|length %}
      newurl = '{{ url1[len-1] }}';
    }
    window.history.replaceState({},null,newurl);
    onScroll();
  });

  function Addactive(element,val){
    element.map(function (){
      data_name = $(this).find('a').data('url');
      if(val === data_name){
          $(this).addClass('pillar-active');
      }else{
          $(this).removeClass('pillar-active');
      }
    });
  }

//   $('.blog-post-pillar-section ul li a').on('click', function(event){     
//     event.preventDefault();
//     $('html,body').animate({scrollTop:$(this.hash).offset().top - 200}, 1000);
//   });

//   $('.post-body-content-wrap a').on('click', function(event){     
//     event.preventDefault();
//     $('html,body').animate({scrollTop:$(this.hash).offset().top - 180}, 1000);
//   });

   function onScroll(){
    var scrollPos = $(document).scrollTop() + wh; 
    $('.blog-post-pillar-section ul li').each(function () {
        var currLink = $(this).children('a');
        var refElement = $(currLink.attr("href"));
        if (refElement.position().top <= scrollPos && refElement.position().top + refElement.height() > scrollPos) {
            var temp = ((scrollPos - refElement.position().top)/refElement.height())*100;
            $(this).prevAll('li').addClass('pillar-active');
            $(this).find('span.progress-bar').css('width',temp+"%");
            $(this).next('li').find('span.progress-bar').css('width',"0%");
           }
       else{
            var temp = ((scrollPos - refElement.position().top)/refElement.height())*100;
            top = $('.blog-section.blog-post-page .post-body-outer').offset().top + $('.blog-section.blog-post-page .post-body-outer').height();
            if(scrollPos<top-200){
               $(this).prev('li').removeClass('pillar-active');
               $(".blog-post-pillar-section ul li:last-child").removeClass("pillar-active");
            }
            $(this).find('span.progress-bar').css('width',temp+"%");
            $(this).next('li').find('span.progress-bar').css('width',"0%");
            $(".blog-post-pillar-section ul li:last-child").removeClass("pillar-active");
        }

    });
   }


});
</script>
